# Homebrew formula for a custom tap (e.g. lolgab/homebrew-scalino), not homebrew-core: core
# requires building from source, and build/all.sh needs vendored, patched scala3+scala-native
# checkouts that don't fit its sandbox. Installs the prebuilt relocatable release tarball (the
# one install.sh fetches).
#
# url/sha256 are regenerated by build/10-update-package-metadata.sh after every tagged release;
# don't hand-edit them.
class Scalino < Formula
  desc "Scala 3 toolchain that compiles straight to native binaries -- no JVM at any step"
  homepage "https://github.com/lolgab/scalino"
  version "0.0.29"
  license "Apache-2.0"

  on_macos do
    on_intel do
      url "https://github.com/lolgab/scalino/releases/download/v#{version}/scalino-v#{version}-macos-x86_64.tar.gz"
      sha256 "0aaaf79e704661054e3f5eeae887bdf29fe056790a466bd873c6adce24dc5fe0"
    end
    on_arm do
      url "https://github.com/lolgab/scalino/releases/download/v#{version}/scalino-v#{version}-macos-arm64.tar.gz"
      sha256 "314f35501b505aeb286ce9d0e769c5b156318b5c7f6de1bb59a0f3fd00a1140e"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/lolgab/scalino/releases/download/v#{version}/scalino-v#{version}-linux-x86_64.tar.gz"
      sha256 "1bcbc454b979a7d29c9b58ee258742c28390232946fc9987481fd4452a984004"
    end
    on_arm do
      url "https://github.com/lolgab/scalino/releases/download/v#{version}/scalino-v#{version}-linux-arm64.tar.gz"
      sha256 "ccaab5304e8d0c0aaeb691dbc97c61f17c3cf8911f37c4022e226ef503452e72"
    end
  end

  depends_on "node" => :optional # runs Scala.js programs (`scalino run --js`); Scala Native builds don't need it
  depends_on "llvm" => :recommended # provides clang/clang++ where the OS doesn't already (Linux); macOS uses Xcode CLT's own
  # coursier's `cs` launcher (needed for `//> using dep`) is bundled in the
  # tarball as scalino-cs -- no separate dependency.

  def install
    libexec.install Dir["*"]
    bin.install_symlink libexec/"scalino"
    bin.install_symlink libexec/"scalino-lsp"
    bin.install_symlink libexec/"scalino-cs"

    # Completions pre-generated by build/07-build-scalino.sh and shipped in the tarball; installed
    # from there rather than by running the installed binary, so it works wherever the formula runs.
    bash_completion.install libexec/"completions/scalino.bash" => "scalino"
    zsh_completion.install libexec/"completions/_scalino"
    fish_completion.install libexec/"completions/scalino.fish"
  end

  test do
    system "#{bin}/scalino", "--help"
  end
end
